(() => {
  const design=document.querySelector('#design');if(!design)return;
  const style=document.createElement('link');style.rel='stylesheet';style.href='design/rationale.css';document.head.append(style);
  const decisions=[
    {id:'01',title:'Gradient & 3D Coins',cn:'渐变背景与 3D 金币',before:'蓝紫渐变背景，右侧展示彩色立体积分图形。',after:'粉橙暖色渐变，以金色 Mi Coins 作为积分资产的主要识别元素。',why:'以暖色焦点突出积分资产，用具象化金币帮助识别奖励，并与下方内容卡片区分层级。',strategy:'VALUE · 积分价值感知',note:'视觉探索，不代表俄罗斯用户已被证实偏好暖色。'},
    {id:'02',title:'Reward Card Design',cn:'奖励卡片',before:'横向排列同级奖励卡片，同时展示商品图、面额与积分价格。',after:'保留横向浏览，以更明确的商品图、奖励面额和所需积分组织信息层级。',why:'区分实际奖励价值与积分门槛，帮助比较不同奖励，降低兑换决策成本。',strategy:'VALUE → ACTION · 支持奖励选择'},
    {id:'03',title:'Task Status & Buttons',cn:'任务状态与操作按钮',before:'以勾选、百分比及 Do it 等不同形式表达状态。',after:'统一为已完成、进行中、未开始三类状态；状态标签与操作按钮分离，分别呈现 Pending、Continue、Start task。',why:'减少状态理解成本，让用户识别当前进展以及下一步操作。',strategy:'ACTION → PROGRESS · 明确任务反馈',note:'状态语义为 Completed / In Progress / Not Started；原导出图的未开始标签写作 “No Started”，此处如实保留截图。'},
    {id:'04',title:'Visual Hierarchy',cn:'信息层级',before:'余额、兑换奖励与任务按功能顺序排列。',after:'模块化卡片、标题层级与区域视觉权重形成阅读路径：A 优先奖励价值与兑换目标；B 优先正在进行的任务。',why:'让两种信息结构分别支持奖励发现和任务行动效率。',strategy:'VALUE → ACTION → PROGRESS · 目标驱动'}
  ];
  const section=document.createElement('div');section.id='visual-rationale';section.className='vr-section';
  section.innerHTML=`<div class="final-kicker">Visual Redesign</div><h2>Visual Redesign Rationale</h2><h3 class="vr-subtitle">从视觉装饰到价值与行动引导。</h3><p class="vr-intro">在保留 Mi Coins 原有核心功能的基础上，通过渐变、3D 金币、奖励卡片以及任务状态组件的系统化重构，强化积分价值感知、奖励浏览效率与操作反馈清晰度。</p><div class="vr-compare"><figure><div class="vr-image-label"><span>BEFORE</span><b>Original Design</b></div><button class="vr-image-button" data-vr-zoom="before" aria-label="放大原始 Mi Coins 中心页"><span class="vr-image-stage vr-original"><img src="assets/brief.png" alt="原始任务书中的 Mi Coins 中心页，蓝紫渐变、横向奖励及多状态任务"><span class="vr-highlight" aria-hidden="true"></span></span></button><figcaption>原始任务书中的中心页视窗 · 点击放大</figcaption></figure><figure><div class="vr-image-label"><span>AFTER</span><b>Redesigned Version</b></div><button class="vr-image-button" data-vr-zoom="after" aria-label="放大方案 A 高保真原始设计"><span class="vr-image-stage vr-after"><img src="assets/final/A1.png" alt="设计师在 Figma 完成的方案 A 原始高保真长图"><span class="vr-highlight" aria-hidden="true"></span></span></button><figcaption>A / Reward-Driven · 设计师 Figma 原始导出</figcaption></figure></div><div class="vr-controls" aria-label="选择视觉改动以高亮对比区域">${decisions.map(d=>`<button data-vr-select="${d.id}" aria-pressed="false"><span>${d.id}</span>${d.cn}</button>`).join('')}</div><div class="vr-decisions">${decisions.map(d=>`<article data-vr-decision="${d.id}"><div class="vr-card-head"><button data-vr-select="${d.id}" aria-label="高亮 ${d.cn} 对比区域">${d.id}</button><div><small>DECISION ${d.id}</small><h3>${d.title}</h3><b>${d.cn}</b></div></div><dl><div><dt>Before</dt><dd>${d.before}</dd></div><div><dt>After</dt><dd>${d.after}</dd></div><div class="vr-why"><dt>Why</dt><dd>${d.why}</dd></div></dl><p class="vr-strategy">${d.strategy}</p>${d.note?`<p class="vr-note">${d.note}</p>`:''}</article>`).join('')}</div><div class="vr-disclosure"><p><b>设计归属与 AI 使用声明：</b>高保真视觉由设计师本人在 Figma 完成；AI 仅协助整理本章节文案、对比排版和前端呈现。以上为设计意图与待验证的体验收益，不代表已获得用户研究或实验验证。</p><a href="https://www.figma.com/design/7AOi6exOBVyEeFMpdWoTbG/Mi-Coins?node-id=0-1" target="_blank" rel="noopener">View Original Design in Figma ↗</a></div><div class="vr-next">NEXT → A/B FINAL UI DESIGN</div>`;
  design.querySelector('.final-gallery').before(section);
  const nav=document.querySelector('header nav'),entry=document.createElement('a');entry.href='#visual-rationale';entry.textContent='视觉重构依据';nav.insertBefore(entry,nav.querySelector('a[href="#design"]'));
  const next=document.querySelector('#strategy .next');if(next){const link=document.createElement('a');link.className=next.className;link.href='#visual-rationale';link.textContent=next.textContent;next.replaceWith(link);}
  const dialog=document.createElement('dialog');dialog.className='vr-zoom';dialog.setAttribute('aria-labelledby','vr-zoom-title');dialog.innerHTML='<div class="vr-zoom-top"><h2 id="vr-zoom-title"></h2><button aria-label="关闭放大图片">×</button></div><div class="vr-zoom-image"></div><a class="vr-source" target="_blank" rel="noopener">查看完整源图片 ↗</a>';document.body.append(dialog);
  dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  section.addEventListener('click',e=>{const zoom=e.target.closest('[data-vr-zoom]');if(zoom){const before=zoom.dataset.vrZoom==='before',stage=zoom.querySelector('.vr-image-stage').cloneNode(true);stage.querySelector('.vr-highlight').remove();dialog.querySelector('#vr-zoom-title').textContent=before?'Original Design':'A / Redesigned Version';dialog.querySelector('.vr-zoom-image').replaceChildren(stage);dialog.querySelector('.vr-source').href=before?'assets/brief.png':'assets/final/A1.png';dialog.showModal();return;}const button=e.target.closest('[data-vr-select]');if(!button)return;const id=button.dataset.vrSelect,active=section.dataset.selected===id?'':id;section.dataset.selected=active;section.querySelectorAll('[data-vr-select]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.vrSelect===active)));section.querySelectorAll('[data-vr-decision]').forEach(c=>c.classList.toggle('vr-active',c.dataset.vrDecision===active));});

})();
